def add_item(todo_list, item, priority):
    """Add an item to the to-do list with the given priority."""
    if item not in todo_list:
        todo_list[item] = [(priority, False)]
    else:
        todo_list[item].append((priority, False))

def remove_item(todo_list, item):
    """Remove an item from the to-do list."""
    if item in todo_list:
        del todo_list[item]

def print_to_do_list(todo_list):
    """Print the to-do list with priority levels."""
    for item, tasks in todo_list.items():
        tasks.sort(key=lambda x: x[0])
        print(f"To-do list: [{item}]")
        for priority, complete in tasks:
            print(f"  - {priority} ({'completed' if complete else 'not completed'})")
        print()

